-- PERIKSA abt-saksi-rapi-3nov (BACA SAJA): fungsi terpasang dan 15 kasus tetap tidak tahu -> lengkap; keluaran satu baris.
SELECT IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_ket_saksi' AND MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(routine_definition, CONCAT(DATABASE(), '.abt_'), 'aps_badilag.abt_'), CHAR(92), ''), ' ', ''), CHAR(9), ''), CHAR(13), ''), CHAR(10), '')) = '69821f39aa74126aebe6a7caa935df47') = 1 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_tahu_lengkap') + (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_objek_tanya') = 2 AND (
(BINARY isian_rtf_tahu_lengkap('Saya tidak tahu;', 'Apakah Tergugat masih memberikan nafkah kepada Penggugat?') = BINARY 'Saya tidak tahu apakah Tergugat masih memberikan nafkah kepada Penggugat') + (BINARY isian_rtf_tahu_lengkap('Saya tidak tahu', 'Apakah saksi tahu proses akad jual beli?') = BINARY 'Saya tidak tahu proses akad jual beli') + (BINARY isian_rtf_tahu_lengkap('Tidak tahu;', 'Pernahkah ada upaya untuk merukunkan Penggugat dan Tergugat?') = BINARY 'saya tidak tahu apakah pernah ada upaya untuk merukunkan Penggugat dan Tergugat') + (BINARY isian_rtf_tahu_lengkap('saya tidak tahu;', 'Berapa penghasilan Pemohon yang saudara ketahui?') = BINARY 'saya tidak tahu berapa penghasilan Pemohon') + (BINARY isian_rtf_tahu_lengkap('Saya tidak pernah melihatnya;', 'Apakah Saudara pernah melihat Tergugat memukul Penggugat?') = BINARY 'Saya tidak pernah melihat Tergugat memukul Penggugat') + (BINARY isian_rtf_tahu_lengkap('Saya tidak mengetahuinya;', 'Apakah Saudara mengetahui kalau Tergugat berselingkuh?') = BINARY 'Saya tidak mengetahui apakah Tergugat berselingkuh') + (BINARY isian_rtf_tahu_lengkap('saya tidak tahu;', 'Apa yang menjadi penyebab sehingga ada kesepakatan itu?') = BINARY 'saya tidak tahu apa yang menjadi penyebab sehingga ada kesepakatan itu') + (BINARY isian_rtf_tahu_lengkap('Saya tidak pernah melihatnya;', 'Apakah saksi melihat dan mendengar Penggugat dan Tergugat bertengkar?') = BINARY 'Saya tidak pernah melihat Penggugat dan Tergugat bertengkar') + (BINARY isian_rtf_tahu_lengkap('Saya tidak tahu;', 'Apakah pekerjaan Pemohon dan berapa penghasilan Pemohon setiap bulan?') = BINARY 'Saya tidak tahu;') + (BINARY isian_rtf_tahu_lengkap('Saya tidak tahu;', 'Apakah saudara pernah melihat Tergugat memarahi Penggugat?') = BINARY 'Saya tidak tahu;') + (BINARY isian_rtf_tahu_lengkap('Masalah nafkah, saya tidak tahu;', 'Apakah Tergugat masih memberikan nafkah kepada Penggugat?') = BINARY 'Masalah nafkah, saya tidak tahu;') + (BINARY isian_rtf_tahu_lengkap('Saya tidak pernah melihatnya, saya hanya mengetahuinya dari cerita Penggugat;', 'Apakah Saudara pernah melihat Tergugat bermain judi?') = BINARY 'Saya tidak pernah melihat Tergugat bermain judi, saya hanya mengetahuinya dari cerita Penggugat') + (BINARY isian_rtf_tahu_lengkap('saya tidak tahu karena saya baru kenal dengan Pemohon tahun lalu;', 'Dimana Pemohon dan Termohon tinggal bersama setelah menikah?') = BINARY 'saya tidak tahu di mana Pemohon dan Termohon tinggal bersama setelah menikah karena saya baru kenal dengan Pemohon tahun lalu') + (BINARY isian_rtf_tahu_lengkap('Saya tidak tahu, Tergugat masih memberi nafkah atau tidak;', 'Apakah selama pisah, Tergugat masih memberi nafkah kepada Penggugat?') = BINARY 'Saya tidak tahu, Tergugat masih memberi nafkah atau tidak;') + (BINARY isian_rtf_tahu_lengkap('Saya kenal dengan Penggugat karena saya tetangganya;', 'Apakah saksi kenal dengan Penggugat?') = BINARY 'Saya kenal dengan Penggugat karena saya tetangganya;')
) = 15, 'SEMUA COCOK', 'BEDA') AS periksa;
